-- My UNA Styled Posts 0.3.0; each statement occupies one physical line.
CREATE TABLE IF NOT EXISTS `nw_styled_posts_entries` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `author` int(11) NOT NULL DEFAULT '0', `added` int(11) NOT NULL DEFAULT '0', `changed` int(11) NOT NULL DEFAULT '0', `title` varchar(255) NOT NULL DEFAULT '', `text` mediumtext NOT NULL, `views` int(11) NOT NULL default '0', `rrate` float NOT NULL default '0', `rvotes` int(11) NOT NULL default '0', `comments` int(11) NOT NULL default '0', `cf` int(11) NOT NULL default '1', `allow_view_to` varchar(16) NOT NULL DEFAULT '3', `status` enum('active','awaiting','failed','hidden') NOT NULL DEFAULT 'active', `status_admin` enum('active','hidden','pending') NOT NULL DEFAULT 'active', `font_name` varchar(32) NOT NULL DEFAULT 'classic', `font_size` smallint NOT NULL DEFAULT 48, `text_color` varchar(7) NOT NULL DEFAULT '#FFFFFF', `text_align` varchar(8) NOT NULL DEFAULT 'center', `background` varchar(32) NOT NULL DEFAULT 'aurora', `background_color` varchar(7) NOT NULL DEFAULT '#6554C0', `background_file` int unsigned NOT NULL DEFAULT 0, `background_previous` int unsigned NOT NULL DEFAULT 0, `text_backdrop` varchar(8) NOT NULL DEFAULT 'none', `backdrop_color` varchar(7) NOT NULL DEFAULT '#000000', `backdrop_opacity` smallint NOT NULL DEFAULT '65', `backdrop_padding` smallint NOT NULL DEFAULT '12', `image_x` smallint NOT NULL DEFAULT '50', `image_y` smallint NOT NULL DEFAULT '50', `image_zoom` smallint NOT NULL DEFAULT '100', `text_direction` varchar(8) NOT NULL DEFAULT 'auto', `text_position` varchar(8) NOT NULL DEFAULT 'auto', `text_x` smallint NOT NULL DEFAULT '50', `text_y` smallint NOT NULL DEFAULT '50', PRIMARY KEY (`id`), FULLTEXT KEY `title_text` (`title`,`text`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `nw_styled_posts_backgrounds` ( `id` int(11) NOT NULL AUTO_INCREMENT, `profile_id` int(10) unsigned NOT NULL, `remote_id` varchar(128) NOT NULL, `path` varchar(255) NOT NULL, `file_name` varchar(255) NOT NULL, `mime_type` varchar(128) NOT NULL, `ext` varchar(32) NOT NULL, `size` bigint(20) NOT NULL, `added` int(11) NOT NULL, `modified` int(11) NOT NULL, `private` int(11) NOT NULL, `dimensions` varchar(12) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `remote_id` (`remote_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `nw_styled_posts_cmts` ( `cmt_id` int(11) NOT NULL AUTO_INCREMENT, `cmt_parent_id` int(11) NOT NULL DEFAULT '0', `cmt_vparent_id` int(11) NOT NULL DEFAULT '0', `cmt_object_id` int(11) NOT NULL DEFAULT '0', `cmt_author_id` int(11) NOT NULL DEFAULT '0', `cmt_level` int(11) NOT NULL DEFAULT '0', `cmt_text` text NOT NULL, `cmt_mood` tinyint(4) NOT NULL DEFAULT '0', `cmt_rate` int(11) NOT NULL DEFAULT '0', `cmt_rate_count` int(11) NOT NULL DEFAULT '0', `cmt_time` int(11) unsigned NOT NULL DEFAULT '0', `cmt_replies` int(11) NOT NULL DEFAULT '0', `cmt_pinned` int(11) NOT NULL default '0', `cmt_cf` int(11) NOT NULL default '1', PRIMARY KEY (`cmt_id`), KEY `cmt_object_id` (`cmt_object_id`,`cmt_parent_id`), FULLTEXT KEY `search_fields` (`cmt_text`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `nw_styled_posts_reactions` ( `id` int(11) NOT NULL AUTO_INCREMENT, `object_id` int(11) NOT NULL default '0', `reaction` varchar(32) NOT NULL default '', `count` int(11) NOT NULL default '0', `sum` int(11) NOT NULL default '0', PRIMARY KEY (`id`), UNIQUE KEY `reaction` (`object_id`, `reaction`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `nw_styled_posts_reactions_track` ( `id` int(11) NOT NULL AUTO_INCREMENT, `object_id` int(11) NOT NULL default '0', `author_id` int(11) NOT NULL default '0', `author_nip` int(11) unsigned NOT NULL default '0', `reaction` varchar(32) NOT NULL default '', `value` tinyint(4) NOT NULL default '0', `date` int(11) NOT NULL default '0', PRIMARY KEY (`id`), KEY `vote` (`object_id`, `author_nip`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `nw_styled_posts_views_track` ( `id` int(11) NOT NULL AUTO_INCREMENT, `object_id` int(11) NOT NULL default '0', `viewer_id` int(11) NOT NULL default '0', `viewer_nip` int(11) unsigned NOT NULL default '0', `date` int(11) NOT NULL default '0', PRIMARY KEY (`id`), KEY `id` (`object_id`,`viewer_id`,`viewer_nip`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET @nwStyledPage = LAST_INSERT_ID();
SET @nwStyledHome = (SELECT `id` FROM `sys_std_pages` WHERE `name` = 'home' LIMIT 1);
SET @nwStyledWidget = LAST_INSERT_ID();

-- Motion backgrounds (0.2.0).
CREATE TABLE IF NOT EXISTS `nw_styled_posts_motion_files` ( `id` int(11) NOT NULL AUTO_INCREMENT, `profile_id` int(10) unsigned NOT NULL, `remote_id` varchar(128) NOT NULL, `path` varchar(255) NOT NULL, `file_name` varchar(255) NOT NULL, `mime_type` varchar(128) NOT NULL, `ext` varchar(32) NOT NULL, `size` bigint(20) NOT NULL, `added` int(11) NOT NULL, `modified` int(11) NOT NULL, `private` int(11) NOT NULL, `dimensions` varchar(12) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `remote_id` (`remote_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


